import { useState, type FormEvent } from "react";

export default function DeliveryForm() {
  const [speed, setSpeed] = useState("standard");
  const price = speed === "express" ? 12 : 4;

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    alert(`${speed} delivery; notes: ${data.get("notes")}`);
  }

  return (
    <form onSubmit={submit}>
      <label>
        Delivery speed
        <select value={speed} onChange={(event) => setSpeed(event.target.value)}>
          <option value="standard">Standard</option>
          <option value="express">Express</option>
        </select>
      </label>
      <strong>Delivery charge: ${price}</strong>
      <textarea name="notes" defaultValue="Leave at reception" />
      <button type="submit">Place order</button>
    </form>
  );
}
